//! 📐️ Actual record publication demand matches the portable target-layout corpus.
use super::*;
#[test]
fn publication_includes_value_destination_and_initialization_headers(){
 let law:serde_json::Value=serde_json::from_str(include_str!("publication.json")).unwrap();let value=size_of::<(u64,u64)>();let output=size_of::<Option<(u64,u64)>>();let live=size_of::<usize>();let row=law["layouts"].as_array().unwrap().iter().find(|row|row["value"].as_u64()==Some(value as u64)&&row["output"].as_u64()==Some(output as u64)&&row["live"].as_u64()==Some(live as u64)).expect("supported native record layout is represented");let demand=NativeRecordStorage::<(u64,u64)>::take_initialized_demand(size_of::<u8>()).unwrap();assert_eq!(demand.copy_bytes,row["copy"].as_u64().unwrap()as usize);assert_eq!(demand.capacity_bytes,0);assert_eq!(demand.depth,1);
}

use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
fn custody_law()->serde_json::Value{serde_json::from_str(include_str!("custody.json")).unwrap()}
fn paid_step(bank:&mut EffectBank,operation:impl FnOnce(&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkPoll)->RetainedWorkOutcome{let grant=bank.loan(1,4096);let((poll,marker),heap)=observe(||bank.run(grant,1,operation));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("synchronous record leaf retained a producer action")};let progress=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(ValueError::retained_progress);assert_eq!(marker.unwrap_or(0),heap.0);if turn.work!=0{assert_eq!(bank.take_admitted(),Some(true))}else{assert_eq!(bank.take_admitted(),None)}bank.post(progress,grant,heap);turn}
#[test]
fn record_initialization_uses_original_performed_receipt(){let law=custody_law();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeRecordStorage::<()>::empty(0);paid_step(&mut bank,|effect|owner.reserve_empty(effect)).result.unwrap();let initialized=paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.initialize(effect)));assert_eq!(initialized.work,u128::from(law["initialize"]["work"].as_u64().unwrap()));assert_eq!(initialized.result.unwrap().progress().copied_bytes,law["initialize"]["copyBytes"].as_u64().unwrap()as usize);assert!(owner.initialized());paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.release(effect))).result.unwrap();assert!(owner.terminal_is_empty());}

#[repr(C)]
struct Pair{left:u32,right:u32}
fn layout<'a>(law:&'a serde_json::Value)->&'a serde_json::Value{law["layouts"].as_array().unwrap().iter().find(|row|row["word"].as_u64()==Some(size_of::<usize>()as u64)).unwrap()}
fn place(bank:&mut EffectBank,owner:&mut NativeRecordStorage<Pair>,offset:usize,value:&mut Option<u32>)->RetainedCloneProgress{paid_step(bank,|effect|{let turn=unsafe{owner.place_field(offset,value,0,effect)};crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|progress|progress.map_or_else(||RetainedCloneStep::Progress(Default::default()),RetainedCloneStep::Complete)),work:turn.work})}).result.unwrap().progress()}
#[test]
fn typed_record_fields_publish_to_the_original_slot_and_release_paid_backing(){
 let law=custody_law();let row=layout(&law);let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeRecordStorage::<Pair>::empty(2);let oracle:(u32,u32)=serde_json::from_value(serde_json::json!([law["values"]["left"],law["values"]["right"]])).unwrap();let mut left=Some(oracle.0);let mut right=Some(oracle.1);let mut output=None;let mut phase=0u8;
 let reserve=paid_step(&mut bank,|effect|owner.reserve_empty(effect));assert_eq!(reserve.result.unwrap().progress().retained_capacity_bytes,size_of::<Pair>());paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.initialize(effect))).result.unwrap();
 let progress=place(&mut bank,&mut owner,std::mem::offset_of!(Pair,left),&mut left);assert_eq!(progress.copied_bytes,row["placement"].as_u64().unwrap()as usize);assert!(left.is_none());assert_eq!(owner.live,1);let progress=place(&mut bank,&mut owner,std::mem::offset_of!(Pair,right),&mut right);assert_eq!(progress.copied_bytes,row["placement"].as_u64().unwrap()as usize);assert!(right.is_none());assert_eq!(owner.live,2);
 let published=paid_step(&mut bank,|effect|{let turn=unsafe{owner.take_initialized_into(&mut output,size_of::<u8>(),effect)};if matches!(&turn,crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(_)),..})){phase=1}turn});assert_eq!(published.result.unwrap().progress().copied_bytes,row["publication"].as_u64().unwrap()as usize);assert_eq!(phase,1);assert_eq!(owner.live,0);assert!(owner.taken());let actual=output.take().unwrap();assert_eq!((actual.left,actual.right),oracle);assert_eq!(serde_json::to_value((actual.left,actual.right)).unwrap(),serde_json::json!([law["values"]["left"],law["values"]["right"]]));
 assert_eq!(owner.release_demand().copy_bytes,row["releaseCopy"].as_u64().unwrap()as usize);let released=paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.release(effect)));assert_eq!(released.result.unwrap().progress().released_bytes,size_of::<Pair>());assert!(owner.terminal_is_empty());assert_eq!(bank.wallet().remaining_work(),law["stock"]["fuel"].as_u64().unwrap()-law["flow"]["work"].as_u64().unwrap());
}
#[test]
fn denied_record_field_and_release_preserve_the_same_original_frontier(){
 let law=custody_law();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeRecordStorage::<Pair>::empty(2);paid_step(&mut bank,|effect|owner.reserve_empty(effect)).result.unwrap();let address=owner.backing.address();let denied=paid_step(&mut bank,|effect|{let grant=RetainedCloneGrant{maximum_copy_bytes:0,..effect.grant()};crate::RetainedWorkPoll::Complete(owner.initialize(&mut effect.reborrow(grant,1).unwrap()))});assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert!(!owner.ready);paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.initialize(effect))).result.unwrap();
 let mut left=Some(law["values"]["left"].as_u64().unwrap()as u32);let mut right=Some(law["values"]["right"].as_u64().unwrap()as u32);let demand=NativeRecordStorage::<Pair>::field_demand::<u32>(0).unwrap();let denied=paid_step(&mut bank,|effect|{let grant=RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..effect.grant()};let turn=unsafe{owner.place_field(std::mem::offset_of!(Pair,left),&mut left,0,&mut effect.reborrow(grant,1).unwrap())};crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|progress|progress.map_or_else(||RetainedCloneStep::Progress(Default::default()),RetainedCloneStep::Complete)),work:turn.work})});assert_eq!(denied.work,0);assert_eq!(left,Some(7));assert_eq!(owner.live,0);assert_eq!(owner.backing.address(),address);
 place(&mut bank,&mut owner,std::mem::offset_of!(Pair,left),&mut left);place(&mut bank,&mut owner,std::mem::offset_of!(Pair,right),&mut right);let mut recovered=None;let denied=paid_step(&mut bank,|effect|{let grant=RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..effect.grant()};crate::RetainedWorkPoll::Complete(unsafe{owner.remove_field::<u32>(std::mem::offset_of!(Pair,left),&mut recovered,0,&mut effect.reborrow(grant,1).unwrap())})});assert_eq!(denied.work,0);assert!(recovered.is_none());assert_eq!(owner.live,2);
 let removed=paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(unsafe{owner.remove_field::<u32>(std::mem::offset_of!(Pair,left),&mut recovered,0,effect)}));assert_eq!(removed.result.unwrap().progress().copied_bytes,demand.copy_bytes);assert_eq!(recovered,Some(7));assert_eq!(owner.live,1);place(&mut bank,&mut owner,std::mem::offset_of!(Pair,left),&mut recovered);let mut output=None;paid_step(&mut bank,|effect|unsafe{owner.take_initialized_into(&mut output,0,effect)}).result.unwrap();let actual=output.take().unwrap();assert_eq!((actual.left,actual.right),(7,19));let release=owner.release_demand();let denied=paid_step(&mut bank,|effect|{let grant=RetainedCloneGrant{maximum_copy_bytes:release.copy_bytes-1,..effect.grant()};crate::RetainedWorkPoll::Complete(owner.release(&mut effect.reborrow(grant,1).unwrap()))});assert_eq!(denied.work,0);assert_eq!(owner.backing.address(),address);assert!(owner.ready);paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.release(effect))).result.unwrap();assert!(owner.terminal_is_empty());assert_eq!(bank.wallet().remaining_work(),law["stock"]["fuel"].as_u64().unwrap()-law["flow"]["work"].as_u64().unwrap()-2);
}

#[test]
fn original_field_transfer_prices_and_records_the_callers_initialization_flag(){
 let law=custody_law();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut owner=NativeRecordStorage::<u32>::empty(1);let mut field=Some(law["values"]["left"].as_u64().unwrap()as u32);let mut initialized=false;let mut output=None;paid_step(&mut bank,|effect|owner.reserve_empty(effect)).result.unwrap();paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.initialize(effect))).result.unwrap();let demand=NativeRecordStorage::<u32>::field_demand::<u32>(size_of::<bool>()).unwrap();assert_eq!(demand.copy_bytes,layout(&law)["placement"].as_u64().unwrap()as usize+law["callerFlag"]["copyBytes"].as_u64().unwrap()as usize);
 let placed=paid_step(&mut bank,|effect|{let turn=unsafe{owner.place_field(0,&mut field,size_of::<bool>(),effect)};if matches!(&turn.result,Ok(Some(_))){initialized=true}crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|progress|progress.map_or_else(||RetainedCloneStep::Progress(Default::default()),RetainedCloneStep::Complete)),work:turn.work})});assert_eq!(placed.result.unwrap().progress().copied_bytes,demand.copy_bytes);assert!(initialized);assert!(field.is_none());
 let denied=paid_step(&mut bank,|effect|{let grant=RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..effect.grant()};let turn=unsafe{owner.remove_field::<u32>(0,&mut output,size_of::<bool>(),&mut effect.reborrow(grant,1).unwrap())};if matches!(&turn.result,Ok(RetainedCloneStep::Complete(_))){initialized=false}crate::RetainedWorkPoll::Complete(turn)});assert_eq!(denied.work,0);assert!(initialized&&output.is_none());
 let removed=paid_step(&mut bank,|effect|{let turn=unsafe{owner.remove_field::<u32>(0,&mut output,size_of::<bool>(),effect)};if matches!(&turn.result,Ok(RetainedCloneStep::Complete(_))){initialized=false}crate::RetainedWorkPoll::Complete(turn)});assert_eq!(removed.result.unwrap().progress().copied_bytes,demand.copy_bytes);assert!(!initialized);assert_eq!(output,Some(7));paid_step(&mut bank,|effect|crate::RetainedWorkPoll::Complete(owner.release(effect))).result.unwrap();assert!(owner.terminal_is_empty());assert_eq!(bank.wallet().remaining_work(),law["stock"]["fuel"].as_u64().unwrap()-law["callerFlag"]["flowWork"].as_u64().unwrap());
}
